namespace NotificationsApp.Services;

public record Notification(int Id, string Message, DateTime Timestamp);

public class NotificationService
{
    private int _nextId = 4;
    private readonly string[] _templates =
    [
        "New comment on your post",
        "Your build succeeded",
        "Deployment to production complete",
        "New pull request review requested",
        "Issue assigned to you",
        "Pipeline failed — check logs",
        "New team member joined your project",
    ];

    /// <summary>Returns the initial set of notifications (called during prerender and interactive init).</summary>
    public Task<List<Notification>> GetNotificationsAsync()
    {
        var initial = new List<Notification>
        {
            new(1, "Welcome to the notification center!", DateTime.UtcNow.AddMinutes(-30)),
            new(2, "Your profile was updated successfully.", DateTime.UtcNow.AddMinutes(-15)),
            new(3, "New deployment started for project Alpha.", DateTime.UtcNow.AddMinutes(-5)),
        };
        return Task.FromResult(initial);
    }

    /// <summary>Simulates checking for new notifications. Returns 0-1 new items per call.</summary>
    public Task<List<Notification>> CheckForNewNotificationsAsync()
    {
        var result = new List<Notification>();

        // ~40% chance of a new notification each poll
        if (Random.Shared.Next(5) < 2)
        {
            var message = _templates[Random.Shared.Next(_templates.Length)];
            result.Add(new(Interlocked.Increment(ref _nextId), message, DateTime.UtcNow));
        }

        return Task.FromResult(result);
    }
}

@page "/notifications"
@rendermode InteractiveServer
@using NotificationsApp.Services
@inject NotificationService NotificationService
@implements IAsyncDisposable

<PageTitle>Notifications</PageTitle>

<h1>
    Notifications
    @if (Items is not null)
    {
        <span class="badge bg-primary rounded-pill ms-2">@Items.Count</span>
    }
</h1>

@if (Items is null)
{
    <p><em>Loading notifications...</em></p>
}
else if (Items.Count == 0)
{
    <p>No notifications.</p>
}
else
{
    <ul class="list-group">
        @foreach (var n in Items.OrderByDescending(x => x.Timestamp))
        {
            <li class="list-group-item d-flex justify-content-between align-items-start">
                <div>
                    <strong>@n.Message</strong>
                    <br />
                    <small class="text-muted">@n.Timestamp.ToString("g")</small>
                </div>
                <span class="badge bg-secondary rounded-pill">#@n.Id</span>
            </li>
        }
    </ul>
}

@code {
    private CancellationTokenSource? _cts;

    [PersistentState]
    public List<Notification>? Items { get; set; }

    protected override async Task OnInitializedAsync()
    {
        // ??= ensures we only fetch when state was NOT restored from prerender
        Items ??= await NotificationService.GetNotificationsAsync();
    }

    protected override void OnAfterRender(bool firstRender)
    {
        if (firstRender)
        {
            // OnAfterRender is never called during prerender,
            // so the polling loop only starts once the page is interactive.
            _cts = new CancellationTokenSource();
            _ = PollForNotificationsAsync(_cts.Token);
        }
    }

    private async Task PollForNotificationsAsync(CancellationToken ct)
    {
        while (!ct.IsCancellationRequested)
        {
            await Task.Delay(TimeSpan.FromSeconds(5), ct);

            try
            {
                var newItems = await NotificationService.CheckForNewNotificationsAsync();
                if (newItems.Count > 0)
                {
                    Items ??= [];
                    Items.AddRange(newItems);
                    await InvokeAsync(StateHasChanged);
                }
            }
            catch (TaskCanceledException)
            {
                break;
            }
        }
    }

    public async ValueTask DisposeAsync()
    {
        if (_cts is not null)
        {
            await _cts.CancelAsync();
            _cts.Dispose();
        }
    }
}

