+@page "/notifications"
+@rendermode InteractiveServer
+@using NotificationsApp.Services
+@inject NotificationService NotificationService
+@implements IAsyncDisposable
+
+<PageTitle>Notifications</PageTitle>
+
+<h1>
+    Notifications
+    @if (Items is not null)
+    {
+        <span class="badge bg-primary rounded-pill ms-2">@Items.Count</span>
+    }
+</h1>
+
+@if (Items is null)
+{
+    <p><em>Loading notifications...</em></p>
+}
+else if (Items.Count == 0)
+{
+    <p>No notifications.</p>
+}
+else
+{
+    <ul class="list-group">
+        @foreach (var n in Items.OrderByDescending(x => x.Timestamp))
+        {
+            <li class="list-group-item d-flex justify-content-between align-items-start">
+                <div>
+                    <strong>@n.Message</strong>
+                    <br />
+                    <small class="text-muted">@n.Timestamp.ToString("g")</small>
+                </div>
+                <span class="badge bg-secondary rounded-pill">#@n.Id</span>
+            </li>
+        }
+    </ul>
+}
+
+@code {
+    private CancellationTokenSource? _cts;
+
+    [PersistentState]
+    public List<Notification>? Items { get; set; }
+
+    protected override async Task OnInitializedAsync()
+    {
+        // ??= ensures we only fetch when state was NOT restored from prerender
+        Items ??= await NotificationService.GetNotificationsAsync();
+    }
+
+    protected override void OnAfterRender(bool firstRender)
+    {
+        if (firstRender)
+        {
+            // OnAfterRender is never called during prerender,
+            // so the polling loop only starts once the page is interactive.
+            _cts = new CancellationTokenSource();
+            _ = PollForNotificationsAsync(_cts.Token);
+        }
+    }
+
+    private async Task PollForNotificationsAsync(CancellationToken ct)
+    {
+        while (!ct.IsCancellationRequested)
+        {
+            await Task.Delay(TimeSpan.FromSeconds(5), ct);
+
+            try
+            {
+                var newItems = await NotificationService.CheckForNewNotificationsAsync();
+                if (newItems.Count > 0)
+                {
+                    Items ??= [];
+                    Items.AddRange(newItems);
+                    await InvokeAsync(StateHasChanged);
+                }
+            }
+            catch (TaskCanceledException)
+            {
+                break;
+            }
+        }
+    }
+
+    public async ValueTask DisposeAsync()
+    {
+        if (_cts is not null)
+        {
+            await _cts.CancelAsync();
+            _cts.Dispose();
+        }
+    }
+}
